SELECT fiscal_year, name, net_sales, operating_income, net_income,
       ROUND(operating_margin * 100, 2) AS operating_margin_pct
FROM m_fin_annual
WHERE sec_code4 = {{sec_code4}}
  AND fiscal_year > (SELECT MAX(fiscal_year) FROM m_fin_annual WHERE sec_code4 = {{sec_code4}} AND net_sales IS NOT NULL) - {{years}}
ORDER BY fiscal_year

SELECT sec_code4, name, industry, ROUND(rnd_ratio * 100, 2) AS rnd_ratio_pct, rnd_expenses, net_sales
FROM m_fin_annual
WHERE fiscal_year = {{fiscal_year}} AND rnd_ratio IS NOT NULL AND rnd_ratio <= 1 AND net_sales >= {{min_sales}}
ORDER BY rnd_ratio DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, employee_count, net_sales,
       ROUND(net_sales / NULLIF(employee_count, 0) / 1000000, 1) AS sales_per_employee_m_yen
FROM m_fin_annual
WHERE fiscal_year = {{fiscal_year}} AND net_sales > 0 AND employee_count >= {{min_employees}}
ORDER BY sales_per_employee_m_yen DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, goodwill, net_assets,
       ROUND(goodwill / NULLIF(net_assets, 0) * 100, 1) AS goodwill_to_net_assets_pct
FROM m_fin_annual
WHERE fiscal_year = {{fiscal_year}} AND goodwill > 0 AND net_assets > {{min_net_assets}}
ORDER BY goodwill_to_net_assets_pct DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, cash_and_equiv, interest_bearing_debt, total_assets,
       ROUND((cash_and_equiv - COALESCE(interest_bearing_debt, 0)) / NULLIF(total_assets, 0) * 100, 1) AS net_cash_to_assets_pct
FROM m_fin_annual
WHERE fiscal_year = {{fiscal_year}} AND cash_and_equiv > 0 AND total_assets >= {{min_assets}}
ORDER BY net_cash_to_assets_pct DESC
LIMIT {{limit}}
